  "cover_credit": "Celette · CC BY-SA 4.0",
  "cover_credit_url": "https://commons.wikimedia.org/wiki/File:Caf%C3%A9_de_Flore,_172_boulevard_Saint-Germain,_Paris_6e.jpg",
  "sources": "[\"https://fr.wikipedia.org/wiki/Le_Procope\",\"https://fr.wikipedia.org/wiki/Café_de_Flore\",\"https://fr.wikipedia.org/wiki/Les_Deux_Magots\",\"https://fr.wikipedia.org/wiki/La_Closerie_des_Lilas\",\"https://cafedeflore.fr\",\"https://www.lesdeuxmagots.fr\",\"https://www.procope.com\"]"
