  "cover_credit_url": "https://commons.wikimedia.org/wiki/File:Cite_Internationale_Universitaire_de_Paris,_4_June_2015.jpg",
  "sources": "[\"https://www.ciup.fr/en/\",\"https://www.campusfrance.org/en\",\"https://www.dzs.cz/\",\"https://www.ifp.cz/cz/kurzy-a-zkousky/zkousky/diplomy-delf-a-dalf/\",\"https://erasmus-plus.ec.europa.eu/\",\"https://www.republiquetcheque.campusfrance.org/\"]"
